insert into public.posts (id, author_id, text, topic, created_at)
values
  ('5eed0002-0000-4000-8000-000000000001', '5eed0001-0000-4000-8000-000000000001', 'Slow mornings are not wasted mornings.', 'life', now() - interval '30294 minutes'),
  ('5eed0002-0000-4000-8000-000000000002', '5eed0001-0000-4000-8000-000000000002', 'You can outgrow a place and still be grateful it held you. #growth', 'growth', now() - interval '29874 minutes'),
  ('5eed0002-0000-4000-8000-000000000003', '5eed0001-0000-4000-8000-000000000003', 'Rest is part of the work, not a reward for it.', 'mindset', now() - interval '29507 minutes'),
  ('5eed0002-0000-4000-8000-000000000004', '5eed0001-0000-4000-8000-000000000004', 'Some doors close so you stop standing in the hallway.', 'life', now() - interval '29140 minutes'),
  ('5eed0002-0000-4000-8000-000000000005', '5eed0001-0000-4000-8000-000000000005', 'Be the friend who remembers the small things.', 'friendship', now() - interval '28757 minutes'),
  ('5eed0002-0000-4000-8000-000000000006', '5eed0001-0000-4000-8000-000000000006', 'Healing is not linear. It is honest. #healing', 'healing', now() - interval '28360 minutes'),
  ('5eed0002-0000-4000-8000-000000000007', '5eed0001-0000-4000-8000-000000000007', 'Your worth was never up for a vote.', 'self-worth', now() - interval '27897 minutes'),
  ('5eed0002-0000-4000-8000-000000000008', '5eed0001-0000-4000-8000-00000000000d', 'Say the kind thing while they can still hear it.', 'relationships', now() - interval '27514 minutes'),
  ('5eed0002-0000-4000-8000-000000000009', '5eed0001-0000-4000-8000-00000000000e', 'Progress looks boring from the inside.', 'motivation', now() - interval '27184 minutes'),
  ('5eed0002-0000-4000-8000-00000000000a', '5eed0001-0000-4000-8000-00000000000f', 'The version of you that you’re becoming is watching. #growth', 'growth', now() - interval '26741 minutes'),
  ('5eed0002-0000-4000-8000-00000000000b', '5eed0001-0000-4000-8000-000000000010', 'Love that asks you to shrink is not love.', 'love', now() - interval '26324 minutes'),
  ('5eed0002-0000-4000-8000-00000000000c', '5eed0001-0000-4000-8000-000000000011', 'Water the friendships that water you back.', 'friendship', now() - interval '25967 minutes'),
  ('5eed0002-0000-4000-8000-00000000000d', '5eed0001-0000-4000-8000-000000000012', 'Quiet confidence doesn’t need an audience.', 'self-worth', now() - interval '25596 minutes'),
  ('5eed0002-0000-4000-8000-00000000000e', '5eed0001-0000-4000-8000-000000000013', 'Not every storm is a sign. Some are just weather. #mindset', 'mindset', now() - interval '25178 minutes'),
  ('5eed0002-0000-4000-8000-00000000000f', '5eed0001-0000-4000-8000-000000000014', 'Choose curiosity over being right.', 'mindset', now() - interval '24799 minutes'),
  ('5eed0002-0000-4000-8000-000000000010', '5eed0001-0000-4000-8000-000000000015', 'You are allowed to change your mind about who you want to be.', 'growth', now() - interval '24412 minutes'),
  ('5eed0002-0000-4000-8000-000000000011', '5eed0001-0000-4000-8000-000000000016', 'Your pace is still a pace.', 'motivation', now() - interval '24000 minutes'),
  ('5eed0002-0000-4000-8000-000000000012', '5eed0001-0000-4000-8000-000000000017', 'The right people make silence comfortable. #relationships', 'relationships', now() - interval '23653 minutes'),
  ('5eed0002-0000-4000-8000-000000000013', '5eed0001-0000-4000-8000-000000000018', 'Start before you feel ready. Ready is a feeling that arrives late.', 'motivation', now() - interval '23256 minutes'),
  ('5eed0002-0000-4000-8000-000000000014', '5eed0001-0000-4000-8000-000000000019', 'Protect your peace like it pays the rent.', 'self-worth', now() - interval '22816 minutes'),
  ('5eed0002-0000-4000-8000-000000000015', '5eed0001-0000-4000-8000-000000000001', 'Soft hearts are strong in ways hard ones never learn.', 'love', now() - interval '22443 minutes'),
  ('5eed0002-0000-4000-8000-000000000016', '5eed0001-0000-4000-8000-000000000002', 'Let the past teach you, not keep you. #healing', 'healing', now() - interval '22015 minutes'),
  ('5eed0002-0000-4000-8000-000000000017', '5eed0001-0000-4000-8000-000000000003', 'Small steps still leave footprints.', 'motivation', now() - interval '21630 minutes'),
  ('5eed0002-0000-4000-8000-000000000018', '5eed0001-0000-4000-8000-000000000004', 'Apologize like you mean to do better.', 'relationships', now() - interval '21253 minutes'),
  ('5eed0002-0000-4000-8000-000000000019', '5eed0001-0000-4000-8000-000000000005', 'Some chapters end mid-sentence. Turn the page anyway.', 'life', now() - interval '20891 minutes'),
  ('5eed0002-0000-4000-8000-00000000001a', '5eed0001-0000-4000-8000-000000000006', 'Talent opens the door. Kindness keeps you in the room. #career', 'career', now() - interval '20497 minutes'),
  ('5eed0002-0000-4000-8000-00000000001b', '5eed0001-0000-4000-8000-000000000007', 'You don’t have to earn rest.', 'self-worth', now() - interval '20083 minutes'),
  ('5eed0002-0000-4000-8000-00000000001c', '5eed0001-0000-4000-8000-00000000000d', 'Grow quietly. Let the results make the noise.', 'growth', now() - interval '19702 minutes'),
  ('5eed0002-0000-4000-8000-00000000001d', '5eed0001-0000-4000-8000-00000000000e', 'Home is the people who notice when you’re gone.', 'love', now() - interval '19294 minutes'),
  ('5eed0002-0000-4000-8000-00000000001e', '5eed0001-0000-4000-8000-00000000000f', 'Discipline is remembering what you want. #motivation', 'motivation', now() - interval '18919 minutes'),
  ('5eed0002-0000-4000-8000-00000000001f', '5eed0001-0000-4000-8000-000000000010', 'The goal is not to be fearless. It’s to be brave with the fear.', 'mindset', now() - interval '18525 minutes'),
  ('5eed0002-0000-4000-8000-000000000020', '5eed0001-0000-4000-8000-000000000011', 'Don’t let one bad day write the whole week.', 'mindset', now() - interval '18089 minutes'),
  ('5eed0002-0000-4000-8000-000000000021', '5eed0001-0000-4000-8000-000000000012', 'Keep a little wonder in your pocket.', 'life', now() - interval '17710 minutes'),
  ('5eed0002-0000-4000-8000-000000000022', '5eed0001-0000-4000-8000-000000000013', 'Listening is the most generous thing you can do. #relationships', 'relationships', now() - interval '17323 minutes'),
  ('5eed0002-0000-4000-8000-000000000023', '5eed0001-0000-4000-8000-000000000014', 'You are not behind. You are on your own timeline.', 'growth', now() - interval '16919 minutes'),
  ('5eed0002-0000-4000-8000-000000000024', '5eed0001-0000-4000-8000-000000000015', 'Care for yourself like someone you love.', 'self-worth', now() - interval '16552 minutes'),
  ('5eed0002-0000-4000-8000-000000000025', '5eed0001-0000-4000-8000-000000000016', 'Say no without writing an essay.', 'self-worth', now() - interval '16138 minutes'),
  ('5eed0002-0000-4000-8000-000000000026', '5eed0001-0000-4000-8000-000000000017', 'Every expert was once a beginner who didn’t quit. #career', 'career', now() - interval '15717 minutes'),
  ('5eed0002-0000-4000-8000-000000000027', '5eed0001-0000-4000-8000-000000000018', 'Tender is not the same as fragile.', 'healing', now() - interval '15374 minutes'),
  ('5eed0002-0000-4000-8000-000000000028', '5eed0001-0000-4000-8000-000000000019', 'The moon doesn’t argue with the dark. It just shines.', 'mindset', now() - interval '15011 minutes'),
  ('5eed0002-0000-4000-8000-000000000029', '5eed0001-0000-4000-8000-000000000001', 'Your story is still being written. Don’t rush the ending.', 'life', now() - interval '14552 minutes'),
  ('5eed0002-0000-4000-8000-00000000002a', '5eed0001-0000-4000-8000-000000000002', 'A good day is made of small, ordinary mercies. #life', 'life', now() - interval '14174 minutes'),
  ('5eed0002-0000-4000-8000-00000000002b', '5eed0001-0000-4000-8000-000000000003', 'Hold on to people who make you feel like yourself.', 'friendship', now() - interval '13786 minutes'),
  ('5eed0002-0000-4000-8000-00000000002c', '5eed0001-0000-4000-8000-000000000004', 'Boundaries are a love language too.', 'relationships', now() - interval '13354 minutes'),
  ('5eed0002-0000-4000-8000-00000000002d', '5eed0001-0000-4000-8000-000000000005', 'Make it simple, then make it good.', 'career', now() - interval '13028 minutes'),
  ('5eed0002-0000-4000-8000-00000000002e', '5eed0001-0000-4000-8000-000000000006', 'You can be a masterpiece and a work in progress. #growth', 'growth', now() - interval '12602 minutes'),
  ('5eed0002-0000-4000-8000-00000000002f', '5eed0001-0000-4000-8000-000000000007', 'Old wounds deserve new gentleness.', 'healing', now() - interval '12200 minutes'),
  ('5eed0002-0000-4000-8000-000000000030', '5eed0001-0000-4000-8000-00000000000d', 'Ask for help. It’s a skill, not a weakness.', 'mindset', now() - interval '11825 minutes'),
  ('5eed0002-0000-4000-8000-000000000031', '5eed0001-0000-4000-8000-00000000000e', 'The best apologies change behavior.', 'relationships', now() - interval '11460 minutes'),
  ('5eed0002-0000-4000-8000-000000000032', '5eed0001-0000-4000-8000-00000000000f', 'Let it be easy when it can be. #life', 'life', now() - interval '11081 minutes'),
  ('5eed0002-0000-4000-8000-000000000033', '5eed0001-0000-4000-8000-000000000010', 'Write the email. Book the ticket. Call your mother.', 'motivation', now() - interval '10605 minutes'),
  ('5eed0002-0000-4000-8000-000000000034', '5eed0001-0000-4000-8000-000000000011', 'A calm mind notices the exits.', 'mindset', now() - interval '10288 minutes'),
  ('5eed0002-0000-4000-8000-000000000035', '5eed0001-0000-4000-8000-000000000012', 'What you tolerate, you teach.', 'relationships', now() - interval '9818 minutes'),
  ('5eed0002-0000-4000-8000-000000000036', '5eed0001-0000-4000-8000-000000000013', 'Joy counts, even when it’s small. #life', 'life', now() - interval '9440 minutes'),
  ('5eed0002-0000-4000-8000-000000000037', '5eed0001-0000-4000-8000-000000000014', 'Friendship is choosing each other on ordinary days.', 'friendship', now() - interval '9051 minutes'),
  ('5eed0002-0000-4000-8000-000000000038', '5eed0001-0000-4000-8000-000000000015', 'Be patient with the version of you that’s still learning.', 'growth', now() - interval '8642 minutes'),
  ('5eed0002-0000-4000-8000-000000000039', '5eed0001-0000-4000-8000-000000000016', 'Some people are sunlight in human form.', 'friendship', now() - interval '8280 minutes'),
  ('5eed0002-0000-4000-8000-00000000003a', '5eed0001-0000-4000-8000-000000000017', 'Your inner voice deserves better manners. #selfworth', 'self-worth', now() - interval '7894 minutes'),
  ('5eed0002-0000-4000-8000-00000000003b', '5eed0001-0000-4000-8000-000000000018', 'The comeback is quieter than the setback. Keep going.', 'motivation', now() - interval '7509 minutes'),
  ('5eed0002-0000-4000-8000-00000000003c', '5eed0001-0000-4000-8000-000000000019', 'Leave room for the life you haven’t imagined yet.', 'life', now() - interval '7108 minutes'),
  ('5eed0002-0000-4000-8000-00000000003d', '5eed0001-0000-4000-8000-000000000001', 'Consistency beats intensity.', 'career', now() - interval '6753 minutes'),
  ('5eed0002-0000-4000-8000-00000000003e', '5eed0001-0000-4000-8000-000000000002', 'You were never too much for the right people. #love', 'love', now() - interval '6291 minutes'),
  ('5eed0002-0000-4000-8000-00000000003f', '5eed0001-0000-4000-8000-000000000003', 'Laugh often. It’s cheaper than therapy and pairs well with it.', 'healing', now() - interval '5981 minutes'),
  ('5eed0002-0000-4000-8000-000000000040', '5eed0001-0000-4000-8000-000000000004', 'Nobody is thinking about your mistake as much as you are.', 'mindset', now() - interval '5554 minutes'),
  ('5eed0002-0000-4000-8000-000000000041', '5eed0001-0000-4000-8000-000000000005', 'Kindness is a form of intelligence.', 'relationships', now() - interval '5145 minutes'),
  ('5eed0002-0000-4000-8000-000000000042', '5eed0001-0000-4000-8000-000000000006', 'The heart heals in its own weather. #healing', 'healing', now() - interval '4799 minutes'),
  ('5eed0002-0000-4000-8000-000000000043', '5eed0001-0000-4000-8000-000000000007', 'Every day is another beginning.', 'motivation', now() - interval '4335 minutes'),
  ('5eed0002-0000-4000-8000-000000000044', '5eed0001-0000-4000-8000-000000000009', '每一天都是新的开始。', 'motivation', now() - interval '3950 minutes'),
  ('5eed0002-0000-4000-8000-000000000045', '5eed0001-0000-4000-8000-000000000008', '今日も新しい始まり。', 'motivation', now() - interval '3600 minutes'),
  ('5eed0002-0000-4000-8000-000000000046', '5eed0001-0000-4000-8000-00000000000a', '오늘은 새로운 시작이다.', 'motivation', now() - interval '3168 minutes'),
  ('5eed0002-0000-4000-8000-000000000047', '5eed0001-0000-4000-8000-00000000000b', 'كل يوم هو بداية جديدة.', 'motivation', now() - interval '2763 minutes'),
  ('5eed0002-0000-4000-8000-000000000048', '5eed0001-0000-4000-8000-00000000000c', 'Каждый день — новое начало.', 'motivation', now() - interval '2390 minutes'),
  ('5eed0002-0000-4000-8000-000000000049', '5eed0001-0000-4000-8000-000000000009', '温柔也是一种力量。', 'self-worth', now() - interval '2036 minutes'),
  ('5eed0002-0000-4000-8000-00000000004a', '5eed0001-0000-4000-8000-000000000008', '小さな一歩も、前に進んでいる。', 'growth', now() - interval '1617 minutes'),
  ('5eed0002-0000-4000-8000-00000000004b', '5eed0001-0000-4000-8000-00000000000a', '천천히 가도 괜찮아.', 'healing', now() - interval '1185 minutes'),
  ('5eed0002-0000-4000-8000-00000000004c', '5eed0001-0000-4000-8000-00000000000b', 'الهدوء قوة.', 'mindset', now() - interval '844 minutes'),
  ('5eed0002-0000-4000-8000-00000000004d', '5eed0001-0000-4000-8000-00000000000c', 'Тишина — тоже ответ.', 'relationships', now() - interval '428 minutes');
